def test_conversion_rate_counts_none_as_not_converted():
    events = [{"converted": True}, {"converted": None}, {"converted": False}]
    assert conversion_rate(events) == 1 / 3
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_by_session_count():
    groups = {"small": [{"converted": True}], "large": [{"converted": False}] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (1, 4), (2, 6), (5, 7)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 4], days) == expected


def test_parse_session_log_skips_lines_and_trims_fields():
    lines = ["", " \t\n", "  # comment", " a , 2 , 1 ", " b , 3 , 0 ", " c , 4 , "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 2, "converted": True},
        {"id": "b", "day": 3, "converted": False},
        {"id": "c", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,3", "x,3,1,extra", "x,not-an-integer,1"])
def test_parse_session_log_reports_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log([" # comment", " ", "valid,3,1", bad_line])


def test_dedupe_sessions_keeps_last_record_and_sorts_by_day_then_id():
    original = {"id": "a", "day": 9, "converted": True}
    replacement = {"id": "a", "day": 2, "converted": False}
    same_day = {"id": "b", "day": 2, "converted": True}
    earlier_day = {"id": "z", "day": 1, "converted": None}
    assert dedupe_sessions([original, same_day, replacement, earlier_day]) == [
        earlier_day, replacement, same_day
    ]


def test_daily_conversion_counts_fills_gaps_and_ignores_out_of_range_sessions():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,4,1", "g,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 4, 1) == []


def test_campaign_summary_uses_calendar_days_and_counts_nonempty_groups():
    groups = {"a": parse_session_log(["a,1,1"]), "b": parse_session_log(["b,4,1", "c,5,0"]), "empty": []}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {"z": [{"converted": True}], "empty": [], "b": [{"converted": False}], "a": [{"converted": True}]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]


def test_conversion_rate_by_group_is_sorted_and_distinguishes_empty_from_zero():
    groups = {"z": [{"converted": True}], "b": [{"converted": False}], "a": []}
    assert list(conversion_rate_by_group(groups).items()) == [("a", None), ("b", 0.0), ("z", 1.0)]


def test_longest_conversion_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 2, 0, 1, -1, 5, 4, 3]) == 3
    assert longest_conversion_streak([0, -2]) == 0
    assert longest_conversion_streak([]) == 0
